const D = { scale:1, energy:.6, warp:.55, speed:1, density:.55, hue:200, x:.5, y:.5, style:'cmyk-print', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = 6.28318530718;
const cl = (v,a,b) => v<a?a:v>b?b:v;
const frr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };

// coarse buffer keyed on aspect (halftone dots computed analytically, upscaled)
const asp = width/height, LS = 224;
let bw, bh;
if (asp >= 1) { bw = LS; bh = Math.max(8, Math.round(LS/asp)); }
else { bh = LS; bw = Math.max(8, Math.round(LS*asp)); }
const bkey = bw+'x'+bh;
if (!S.g || S.bkey !== bkey) { if (S.g && S.g.remove) S.g.remove(); S.g = createGraphics(bw,bh); S.g.pixelDensity(1); S.bkey = bkey; }
const g = S.g;

// seeded source offsets (rebuild caches on seed change)
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  S.o1 = frr(1)*40; S.o2 = frr(2)*40; S.o3 = frr(3)*TAU; S.ph = frr(4)*TAU; S.hoff = frr(5)*0.35;
}

const st = P.style;
const sc = cl(P.scale, 0.4, 2.4);
const en = cl(P.energy, 0, 1);
const dens = cl(P.density, 0, 1);
const spd = cl(P.speed, 0, 3);
const wp = cl(P.warp, 0, 1);

// motion floor — all on K.t (never re-phases)
const boil = K.t * (0.038 + spd*0.09);                      // source domain-warp advection (primary)
const rot  = K.t * (0.003 + spd*0.003) + K.section*0.012;   // gentle whole-screen rotation (about center)
const cellBreath = 1 + 0.05*Math.sin(K.t*0.05*(0.5+spd));   // dot-frequency breathing -> rosette morph
const hbw = bw*0.5, hbh = bh*0.5;                            // rotation pivot (center, avoids corner-strobe)
const reg = (Math.sin(K.t*0.09)*0.9 + Math.sin(K.t*0.13+1.7)*0.6) + A.treble*2.4; // riso misregistration (px)

// dot cell size in buffer px (pop-art = big bold Ben-Day dots)
let cellPx = Math.max(3.0, 6.4*sc) * cellBreath;
if (st === 'pop-art') cellPx *= 1.9;
const inv = 1/cellPx;

// ink coverage / exposure (energy + section arc + bass on top of baseline)
const expo = 0.5 + en*0.95 + K.intensity*0.3 + A.bass*0.5;

// source feature scale + warp depth
const featScale = 2.4 + dens*2.6;
const warpAmt = 0.15 + wp*0.75;
const h0 = P.hue/360 + S.hoff + K.section*0.02;

// iq cosine palette -> colorful source RGB
function pal(t){
  return [
    0.5+0.5*Math.cos(TAU*(t + h0 + 0.00)),
    0.5+0.5*Math.cos(TAU*(t + h0 + 0.33)),
    0.5+0.5*Math.cos(TAU*(t + h0 + 0.67))
  ];
}
// thermal false-color ramp (deep-blue -> magenta -> orange -> yellow-white)
function thermal(t){ t = cl(t,0,1);
  const stops = [[0.04,0.03,0.22],[0.52,0.06,0.55],[0.96,0.34,0.06],[1,0.95,0.72]];
  const f = t*3, i = f>=3?2:(f|0), u = f - i;
  const a = stops[i], b = stops[i+1];
  return [a[0]+(b[0]-a[0])*u, a[1]+(b[1]-a[1])*u, a[2]+(b[2]-a[2])*u];
}

// rotated screen angles (classic C15 / M75 / Y0 / K45), all drift together on rot
function cs(deg){ const a = rot + deg*0.01745329; return [Math.cos(a), Math.sin(a)]; }
const cC = cs(15), cM = cs(75), cY = cs(0), cK = cs(45);

// analytic rotated dot-screen: nearest-dot distance -> anti-aliased ink coverage
function dotInk(x, y, ca, sa, ox, oy, cov){
  if (cov <= 0.002) return 0;
  const xr = (x*ca - y*sa) - ox;
  const yr = (x*sa + y*ca) - oy;
  let fx = xr*inv; fx = fx - Math.floor(fx) - 0.5;
  let fy = yr*inv; fy = fy - Math.floor(fy) - 0.5;
  const d = Math.sqrt(fx*fx + fy*fy);
  const r = Math.sqrt(cl(cov,0,1))*0.62;   // dot radius (cell units); area ~ coverage
  const aaw = 1.5*inv;                      // soft edge AA (tames dot-flicker strobe, stays crisp upscaled)
  const a = (r - d)/aaw + 0.5;
  return a<0?0:a>1?1:a;
}

g.loadPixels();
const px = g.pixels;
const invW = 1/(bw-1), invH = 1/(bh-1);
let idx = 0;
for (let yy = 0; yy < bh; yy++){
  const ny = yy*invH;
  for (let xx = 0; xx < bw; xx++){
    const nx = xx*invW;
    // drifting domain-warped source field
    const fx0 = nx*featScale + S.o1;
    const fy0 = ny*featScale + S.o2;
    const wx = Math.sin(fy0*1.3 + boil)*warpAmt + Math.sin(fy0*2.6 - boil*0.7)*warpAmt*0.5;
    const wy = Math.sin(fx0*1.1 - boil*0.9)*warpAmt + Math.sin(fx0*2.3 + boil*0.6)*warpAmt*0.5;
    const aa = fx0 + wx, bb = fy0 + wy;
    const f1 = 0.5+0.5*Math.sin(aa*1.7 + bb*0.9 + boil*0.5);
    const f2 = 0.5+0.5*Math.sin(aa*0.8 - bb*1.6 + S.ph + boil*0.3);
    const f3 = 0.5+0.5*Math.sin((aa+bb)*1.15 + S.o3 + boil*0.4);

    let R, G, B;
    if (st === 'thermal'){
      const heat = cl(0.15 + f3*0.7 + f1*0.2, 0, 1);
      const tc = thermal(heat);
      const cov = cl((0.12 + heat*0.95)*expo, 0, 1);
      const ink = dotInk(xx-hbw, yy-hbh, cK[0], cK[1], 0, 0, cov);
      R = 0.03 + ink*tc[0]; G = 0.03 + ink*tc[1]; B = 0.09 + ink*tc[2];
    } else if (st === 'monochrome-halftone'){
      const lum = cl(f1*0.5 + f3*0.5, 0, 1);
      const cov = cl((1 - lum)*1.05*expo, 0, 1);       // ink where source is dark
      const ink = dotInk(xx-hbw, yy-hbh, cK[0], cK[1], 0, 0, cov);
      const v = 0.97*(1 - ink*0.90);
      R = v; G = v; B = v*0.985;
    } else if (st === 'riso'){
      const covA = cl(f1*1.1*expo, 0, 1);
      const covB = cl(f2*1.1*expo, 0, 1);
      const s1 = pal(0.02), s2 = pal(0.46);            // two spot inks from hue palette
      const inkA = dotInk(xx-hbw, yy-hbh, cC[0], cC[1], reg, 0, covA);
      const inkB = dotInk(xx-hbw, yy-hbh, cM[0], cM[1], -reg, reg*0.7, covB);
      R = 0.97*(1 - inkA*(1-s1[0]))*(1 - inkB*(1-s2[0]));
      G = 0.95*(1 - inkA*(1-s1[1]))*(1 - inkB*(1-s2[1]));
      B = 0.90*(1 - inkA*(1-s1[2]))*(1 - inkB*(1-s2[2]));
    } else {
      // cmyk-print (default) & pop-art share the 4-channel separation
      const phase = f1*1.0 + f2*0.45;
      const col = pal(phase);
      const bright = 0.28 + 0.66*f3;
      let sr = cl(col[0]*bright*1.18, 0, 1);
      let sg = cl(col[1]*bright*1.18, 0, 1);
      let sb = cl(col[2]*bright*1.18, 0, 1);
      if (st === 'pop-art'){ sr = Math.round(sr*3)/3; sg = Math.round(sg*3)/3; sb = Math.round(sb*3)/3; }
      const mx = sr>sg?(sr>sb?sr:sb):(sg>sb?sg:sb);
      const K1 = 1 - mx;
      const ik = K1 < 0.999 ? 1/(1-K1) : 0;
      const cCov = cl((1-sr-K1)*ik*expo, 0, 1);
      const mCov = cl((1-sg-K1)*ik*expo, 0, 1);
      const yCov = cl((1-sb-K1)*ik*expo, 0, 1);
      const kCov = cl(K1*expo*0.72, 0, 1);
      const iC = dotInk(xx-hbw, yy-hbh, cC[0], cC[1], 0, 0, cCov);
      const iM = dotInk(xx-hbw, yy-hbh, cM[0], cM[1], 0, 0, mCov);
      const iY = dotInk(xx-hbw, yy-hbh, cY[0], cY[1], 0, 0, yCov);
      const iK = dotInk(xx-hbw, yy-hbh, cK[0], cK[1], 0, 0, kCov);
      R = 0.97*(1-iC*0.90)*(1-iM*0.08)*(1-iY*0.01)*(1-iK*0.90);
      G = 0.965*(1-iC*0.28)*(1-iM*0.88)*(1-iY*0.10)*(1-iK*0.90);
      B = 0.95*(1-iC*0.10)*(1-iM*0.45)*(1-iY*0.90)*(1-iK*0.90);
    }
    px[idx]   = R<0?0:R>1?255:R*255;
    px[idx+1] = G<0?0:G>1?255:G*255;
    px[idx+2] = B<0?0:B>1?255:B*255;
    px[idx+3] = 255;
    idx += 4;
  }
}
g.updatePixels();

drawingContext.imageSmoothingEnabled = true;
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// audio sparkle on TOP of the clk baseline (silent during validation -> baseline carries motion)
if ((A.treble||0) > 0.06 || (A.rms||0) > 0.10){
  push(); blendMode(ADD); noStroke();
  const u = Math.min(width, height);
  const n = Math.min(10, Math.floor(11*(A.treble + A.rms*0.5)));
  const jb = Math.floor(K.beat*2);
  for (let s = 0; s < n; s++){
    const gx = (frr(s*3.1 + jb)) * width;
    const gy = (frr(s*5.7 + jb + 1)) * height;
    fill(0, 0, 100, 32*A.treble + 14*A.rms);
    circle(gx, gy, u*0.010);
  }
  blendMode(BLEND); pop();
}
